<?php require 'config.php'; require_login(); $uid=$_SESSION['uid']; $gid=(int)($_GET['g'] ?? $_POST['g'] ?? 0);
const GKINDS=['couple'=>'Couple','family'=>'Family','roommates'=>'Roommates','other'=>'Other'];
$role=null; if ($gid) { $r=$pdo->prepare('SELECT role FROM group_members WHERE group_id=? AND user_id=?'); $r->execute([$gid,$uid]); $role=$r->fetchColumn() ?: null; if (!$role) { $gid=0; } }
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $a=$_POST['action'] ?? '';
  if ($a==='create') { $n=mb_substr(trim($_POST['name'] ?? ''),0,80); if ($n!=='') { $pdo->prepare('INSERT INTO groups_(name,kind,owner_id) VALUES(?,?,?)')->execute([$n,array_key_exists($_POST['kind'] ?? '',GKINDS)?$_POST['kind']:'other',$uid]); $g=(int)$pdo->lastInsertId();
      $pdo->prepare("INSERT INTO group_members(group_id,user_id,role) VALUES(?,?,'owner')")->execute([$g,$uid]); header('Location: groups.php?g='.$g); exit; } }
  elseif ($gid && $a==='member' && $role==='owner') { $s=$pdo->prepare('SELECT id FROM users WHERE email=?'); $s->execute([strtolower(trim($_POST['email'] ?? ''))]); $m=$s->fetchColumn();
    if (!$m) flash('No FinTrack user has that email. Ask them to register first.'); else { $pdo->prepare('REPLACE INTO group_members(group_id,user_id,role) VALUES(?,?,?)')->execute([$gid,$m,in_array($_POST['role'] ?? '',['editor','viewer'])?$_POST['role']:'editor']); flash('Member added.'); } }
  elseif ($gid && $a==='expense' && in_array($role,['owner','editor'])) { $amt=(float)($_POST['amount'] ?? 0); $d=mb_substr(trim($_POST['description'] ?? ''),0,120); $dt=DateTime::createFromFormat('Y-m-d',$_POST['date'] ?? '');
    if ($amt>0 && $d!=='' && $dt) { $pdo->prepare('INSERT INTO group_expenses(group_id,paid_by,description,amount,spent_on) VALUES(?,?,?,?,?)')->execute([$gid,$uid,$d,$amt,$dt->format('Y-m-d')]); flash('Shared expense added and split equally.'); } else flash('Enter a description, an amount and a date.'); }
  elseif ($gid && $a==='leave') { $pdo->prepare('DELETE FROM group_members WHERE group_id=? AND user_id=?')->execute([$gid,$uid]); flash('You left the group.'); header('Location: groups.php'); exit; }
  header('Location: groups.php'.($gid?'?g='.$gid:'')); exit; }
page_head('Shared budgets'); echo '<h1>Shared budgets &amp; expense splitting</h1>';
if (!$gid) { $s=$pdo->prepare('SELECT g.*,gm.role FROM groups_ g JOIN group_members gm ON gm.group_id=g.id WHERE gm.user_id=?'); $s->execute([$uid]); ?>
<div class="card scroll"><table><tr><th>Group</th><th>Kind</th><th>Your role</th><th></th></tr><?php foreach ($s as $g) echo '<tr><td>'.e($g['name']).'</td><td>'.e(GKINDS[$g['kind']]).'</td><td>'.e($g['role']).'</td><td><a href="groups.php?g='.$g['id'].'">Open</a></td></tr>'; ?></table></div>
<form method="post" class="card narrow"><?= csrf() ?><input type="hidden" name="action" value="create"><h2 style="margin-top:0">Start a group</h2><label>Name<input name="name" required maxlength="80" placeholder="e.g. Flat 4B, Our family"></label><label>Kind<select name="kind"><?php foreach (GKINDS as $k=>$v) echo '<option value="'.$k.'">'.e($v).'</option>'; ?></select></label><button class="btn">Create</button></form>
<?php } else { $g=$pdo->prepare('SELECT * FROM groups_ WHERE id=?'); $g->execute([$gid]); $g=$g->fetch();
  $m=$pdo->prepare('SELECT u.id,u.name,gm.role FROM group_members gm JOIN users u ON u.id=gm.user_id WHERE gm.group_id=?'); $m->execute([$gid]); $mem=$m->fetchAll(); $N=max(1,count($mem));
  $ex=$pdo->prepare('SELECT e.*,u.name FROM group_expenses e JOIN users u ON u.id=e.paid_by WHERE e.group_id=? ORDER BY e.spent_on DESC,e.id DESC'); $ex->execute([$gid]); $exps=$ex->fetchAll();
  $bal=[]; foreach ($mem as $x) $bal[$x['id']]=0; $total=0; foreach ($exps as $e_) { $total+=$e_['amount']; if (isset($bal[$e_['paid_by']])) $bal[$e_['paid_by']]+=$e_['amount']; foreach ($bal as $k=>$_) $bal[$k]-=$e_['amount']/$N; }
  $names=array_column($mem,'name','id'); ?>
<p><a href="groups.php">&larr; All groups</a></p><h2 style="margin-top:0"><?= e($g['name']) ?> <span class="pill"><?= e(GKINDS[$g['kind']]) ?></span> <span class="pill">you: <?= e($role) ?></span></h2>
<div class="grid two"><div class="card"><b>Members</b><ul><?php foreach ($mem as $x) echo '<li>'.e($x['name']).' <span class="note">('.e($x['role']).')</span></li>'; ?></ul>
<?php if ($role==='owner'): ?><form method="post"><?= csrf() ?><input type="hidden" name="g" value="<?= $gid ?>"><input type="hidden" name="action" value="member"><label>Add by email<input type="email" name="email" required></label><label>Permission<select name="role"><option value="editor">Can add expenses</option><option value="viewer">View only</option></select></label><button class="btn">Add member</button></form><?php else: ?><form method="post" data-confirm="Leave this group?"><?= csrf() ?><input type="hidden" name="g" value="<?= $gid ?>"><input type="hidden" name="action" value="leave"><button class="link">Leave group</button></form><?php endif; ?></div>
<div class="card"><b>Who owes whom</b> <span class="note">(total shared: <?= money($total) ?>)</span><?php $debt=[]; $cred=[]; foreach ($bal as $k=>$v) { if ($v<-0.01) $debt[$k]=-$v; elseif ($v>0.01) $cred[$k]=$v; } $lines=[];
 foreach ($debt as $d=>$da) foreach ($cred as $c=>&$ca) { if ($da<=0.01) break; $p=min($da,$ca); if ($p>0.01) { $lines[]=e($names[$d]).' owes '.e($names[$c]).' <b>'.money($p).'</b>'; $da-=$p; $ca-=$p; } } unset($ca);
 echo $lines?'<ul><li>'.implode('</li><li>',$lines).'</li></ul>':'<p>Everyone is settled up.</p>'; ?></div></div>
<?php if (in_array($role,['owner','editor'])): ?><form method="post" class="card narrow"><?= csrf() ?><input type="hidden" name="g" value="<?= $gid ?>"><input type="hidden" name="action" value="expense"><h3 style="margin-top:0">Add a shared expense (you paid)</h3><label>What for<input name="description" required maxlength="120" placeholder="e.g. Rent, groceries"></label><label>Amount<input type="number" step="0.01" min="0.01" name="amount" required></label><label>Date<input type="date" name="date" value="<?= date('Y-m-d') ?>" required></label><button class="btn">Add and split equally</button></form><?php endif; ?>
<div class="card scroll"><table><tr><th>Date</th><th>What</th><th>Paid by</th><th class="r">Amount</th></tr><?php foreach ($exps as $e_) echo '<tr><td>'.e($e_['spent_on']).'</td><td>'.e($e_['description']).'</td><td>'.e($e_['name']).'</td><td class="r">'.money($e_['amount']).'</td></tr>'; if (!$exps) echo '<tr><td colspan="4">No shared expenses yet.</td></tr>'; ?></table></div><?php }
page_foot();
